# Define the tt_state_t structure and its functions
class tt_state_t(ctypes.Structure):
    _fields_ = [("seed", ctypes.c_ulong), ("state", ctypes.c_long)]

tt_set = gsl.gsl_testrng_set
tt_get = gsl.gsl_testrng_get

def generate_random_number(seed):
    # Initialize the tt_state_t structure with the given seed value
    state = tt_state_t()
    state.seed = seed
    tt_set(state)

    # Generate a random unsigned long integer using the tt_get function
    result = ctypes.c_ulong(0)
    tt_get(ctypes.byref(state), ctypes.byref(result))

    return int(result.value)

# Define the main function to generate and return the random number
