class GSLVector:
    def __init__(self, size):
        self.array = (ctypes.c_double * size)()

    def get(self):
        return np.ctypeslib.as_array(self.array)

    def set(self, vector):
        for i in range(len(vector)):
            self.array[i] = vector[i]

def gsl_vector_add(a, b):
    vec_a = GSLVector(len(a))
    vec_b = GSLVector(len(b))

    for i in range(len(a)):
        vec_a.set((np.array(a))[i],)
        vec_b.set((np.array(b))[i],)

    result = (ctypes.c_double * len(a))()
    for i in range(len(a)):
        result[i] = gsl.cblas_dswap_size1(&a[i], &b[i])

    return list(result.get())

