            error = "Failed to allocate memory"
        else:
            result = {\"status\": True}
            return json.dumps(result)
    except Exception as e:
        error = str(e)
    finally:
        try:
            if workspace != 0:
                gsl.gsl_sum_levin_utrunc_free(workspace)
        except:
            pass
    result = {\"status\": False, \"error\": "{}".format(error)}
