import ctypes
import json
from ctypes.util import find_library
gslcblas = ctypes.CDLL(find_library('gslcblas'), mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL(find_library('gsl'), mode=ctypes.RTLD_GLOBAL)

class Combination:
    def __init__(self, n, k):
        self.n = n
        self.k = k
        self.gsl_combination_ptr = None

    def create(self):
        if self.create_first_combination(self.n, self.k) == 0:
            return None
        else:
            return self.to_list()

    def to_list(self):
        combination = [0] * (self.k + 1)
        for i in range(self.k + 1):
            combination[i] = int(gsl.gsl_combination_get(self.gsl_combination_ptr, i))
        return combination

    def create_first_combination(self, n, k):
        self.gsl_combination_ptr = gsl.gsl_combination_alloc(n, k)
        if self.gsl_combination_ptr is None:
            return -1
        else:
            gsl.gsl_combination_init_first(self.gsl_combination_ptr)
            return 0

    def free(self):
        if self.gsl_combination_ptr is not None:
            gsl.gsl_combination_free(self.gsl_combination_ptr)
            self.gsl_combination_ptr = None

def solution(n, k):
    combination = Combination(n, k)
    result = combination.create()
    return json.dumps({'Candidate_solution': str(result)})

