def gsl_pow_int(base, exponent):
    if base == 0 and exponent < 0:
        return float('inf')
    elif base == 0 and exponent > 0:
        return 0.0
    elif base < 0 or exponent < 0:
        result = float(gsl.gsl_pow_int(1, abs(base), abs(exponent)))
    else:
        result = float(gsl.gsl_pow_int(abs(base), exponent))

    if ctypes.c_double(result).value < 0.0:
        return -result
    else:
        return result

