class MedianAccumulator:
    def __init__(self):
        self.acc = ctypes.POINTER(ctypes.c_double)()

    def insert(self, data):
        gsl.gsl_sort.push(self.acc, len(data), data.ctypes.data_as(ctypes.POINTER(ctypes.c_double)))
        return

    def retrieve_median(self):
        median = np.zeros(1)
        gsl.gsl_stats.median_r(self.acc, median.ctypes.data_as(ctypes.POINTER(ctypes.c_double)), 0)
        return float(median)

def compute_moving_median(data, window_size):
    medians = []
    acc = MedianAccumulator()

    for i in range(len(data) - window_size + 1):
        window_data = data[i:i+window_size]
        acc.insert(window_data)
        median = acc.retrieve_median()
        medians.append(median)

    return medians

def solution(input_list, window_size):
    return str(compute_moving_median(np.array(input_list).flatten(), window_size))

