    def set_size(self, n):
        self._ptr = (ctypes.c_int*n)(1)
    def resize(self, n):
        if n != len(self._ptr):
            self.set_size(n)
    def is_valid(self):
        return self._ptr[0] == 0
    def swap_elements(self, i, j):
        if i < 0 or i >= len(self._ptr) or j < 0 or j >= len(self._ptr):
            raise IndexError("Index out of range")
        self._ptr[i], self._ptr[j] = self._ptr[j], self._ptr[i]
class gsl_vector:
    _ptr = ctypes.POINTER(ctypes.c_double)
    def __init__(self, n):
        self._ptr = (ctypes.POINTER(ctypes.c_double)*n)(0)
    def resize(self, n):
        if n != len(self._ptr):
            self._ptr = (ctypes.POINTER(ctypes.c_double)*n)(0)
    def __getitem__(self, i):
        return self._ptr[i][0]
    @property
    def size(self):
        return len(self._ptr)
def permute_vector(perm, vec):
    if len(perm) != len(vec):
        raise ValueError("Permutation and vector lengths differ")
    p = gsl_permutation()
    for i in range(len(perm)):
        p.set_size(len(vec))
        p.resize(len(vec))
        p.is_valid()
        p.swap_elements(perm[i], i)
    v = gsl_vector(len(vec))
    for i in range(len(vec)):
        v._ptr[i] = vec[perm[i]]
    return [v.__getitem__(i) for i in range(len(v))]

