class gsl_matrix_complex(ctypes.Structure):
    _fields_ = [('data', ctypes.POINTER(ctypes.c_double))]
    def __init__(self, size):
        self.data = ctypes.POINTER(ctypes.c_double)(0)
        for i in range(size**2):
            self.data[i] = ctypes.c_double(0.0)

    @property
    def real(self):
        return np.fromiter((self.data[i].value for i in range(self.size**2)), dtype=np.float64).reshape(self.size, self.size)
    @property
    def imag(self):
        return np.fromiter((ctypes.c_double(0.0) for _ in range(self.size**2)), dtype=np.float64).reshape(self.size, self.size)

    @real.setter
    def real(self, value):
        a = (value.flatten()).tobytes()
        ctypes.memmove(self.data, a.encode('utf-8'), len(a) * 4)

    @imag.setter
    def imag(self, value):
        a = (value.flatten()).tobytes()
        ctypes.memmove((self.data + self.size**2).cast(ctypes.POINTER(ctypes.c_double)), a.encode('utf-8'), len(a) * 4)

    @property
    def size(self):
        return int(np.sqrt(len(self.real.flat)))

