        raise ValueError("Invalid dimension")

    state_ptr = gsl.gsl_qrng_niederreiter_init(ctypes.c_int(dimension))
    point = np.zeros((dimension,))
    for i in range(dimension):
        point[i] = ctypes.c_double(0)
    try:
        for _ in range(1):
            c_state_ptr = ctypes.pointer(state_ptr)
            c_point = (ctypes.POINTER(ctypes.c_double) * dimension)(*point)
            gslcblas.gsl_cblas_qrng_niederreiter_generate(c_state_ptr, c_point)
