def write_and_read_permutation(perm_list):
    n = len(perm_list)
    perm = Permutation(n)
    for i in range(n):
        perm._ptr[i] = c_int(perm_list[i])
    file_path = "gsl_permutation.txt"
    f = open(file_path, "wb")
    try:
        gsl.permutation_fwrite(c_void_p(perm._ptr), c_int(n))
    except OSError as e:
        print(f"Error writing permutation to {file_path}: {e.strerror}")
    finally:
        f.close()

    perm = Permutation(n)
    try:
        f = open(file_path, "rb")
        gsl.permutation_fread(c_void_p(perm._ptr), c_int(n))
    except OSError as e:
        print(f"Error reading permutation from {file_path}: {e.strerror}")
    finally:
        f.close()

    read_perm_list = [
        perm._ptr[i].value for i in range(n)
    ]
    return json.dumps(read_perm_list)

