GSL = CDLL('/usr/local/gsl/lib/libgsl.so', mode=ctypes.RTLD_GLOBAL)
cblas = CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctyles.RTLD_GLOBAL)

class GSLMatrix:
    def __init__(self, matrix):
        self.shape = (len(matrix), len(matrix[0]))
        self.data = GSL.new_double_array((self.shape[0], self.shape[1]))
        for i in range(self.shape[0]):
            for j in range(self.shape[1]):
                self.data[i][j] = matrix[i][j]

    def __del__(self):
        GSL.gsl_vector_free_array(self.data)

class GSLVector:
    def __init__(self, vector):
        self.shape = (len(vector), 1)
        self.data = GSL.new_double_array((self.shape[0], 1))
        for i in range(self.shape[0]):
            self.data[i][0] = vector[i]

    def __del__(self):
        GSL.gsl_vector_free_array(self.data)

def numpy_to_gsl_matrix(matrix):
    return GSLMatrix(np.array(matrix, dtype=np.double))

def numpy_to_gsl_vector(vector):
    return GSLVector(np.array(vector, dtype=np.double))

gsl_linalg_QR_UD_decomp = cblas.gsl_linalg_QR_UD_decomp

def qr_ud_decomp(U, D, Y, T):
    U_gsl = numpy_to_gsl_matrix(U)
    D_gsl = GSL.new_double_array((len(D), 1))
    for i in range(len(D)):
        D_gsl[i][0] = D[i]
    Y_gsl = numpy_to_gsl_vector(Y)
    T_gsl = numpy_to_gsl_matrix(T)

    gsl_linalg_QR_UD_decomp(U_gsl.data, D_gsl, Y_gsl.data, T_gsl.data)

    return Y_gsl.data.tolist(), T_gsl.data.tolist()

