from ctypes import c_int, c_double
from collections import deque

gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so", mode=ctypes.RTLD_GLOBAL)
ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)

class RingBuf:
    def __init__(self, size):
        self.size = size
        self.ringbuf = [0] * size
        self.head = 0
        self.tail = 0
        self.is_full = False

    def initialize_ringbuf(self, size):
        return ctypes.c_int().from_param(self)

    def insert_into_ringbuf(self, values):
        for value in values:
            if self.is_full:
                self.head = (self.head + 1) % self.size
            self.ringbuf[self.tail] = value
            self.tail = (self.tail + 1) % self.size
            if self.tail == self.head:
                self.is_full = True
        return self

    def copy_ringbuf_to_list(self):
        temp = deque([0] * self.size)
        for i in range(self.size):
            temp.appendleft(self.ringbuf[i])
        return list(temp)

def main(values):
    ringbuf = RingBuf(5)
    ringbuf.initialize_ringbuf(5)
    inserted_ringbuf = ringbuf.insert_into_ringbuf(values)
    output_list = inserted_ringbuf.copy_ringbuf_to_list()
    return str(output_list)

